// بنك أسئلة الأنمي — 14 أنمي × 18 سؤال (6 سهل / 6 متوسط / 6 صعب)
// img = صورة تطلع مع السؤال (اختيارية)، aImg = صورة تطلع وقت كشف الجواب
// أي صورة ناقصة يتجاهلها العرض ويكمل بدونها
export const ANIME_LIST = ["One Piece", "Naruto", "Attack on Titan", "Death Note", "Bleach", "Hunter x Hunter", "Demon Slayer", "Jujutsu Kaisen", "Berserk", "Solo Leveling", "Hajime no Ippo", "Fairy Tail", "The Seven Deadly Sins", "Dr. Stone"];

// مجلد الصور لكل أنمي: public/img/anime/<slug>/ — "The Seven Deadly Sins" -> seven-deadly-sins
export const animeSlug = (name) => name.toLowerCase().replace(/^the\s+/, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
// صور الأسئلة داخل مجلدات الأنمي وصور البوسترات تنعرض بصندوق مربع ثابت، مهما كانت دقتها
export const isBoxImg = (src) => /^\/img\/(anime\/[^/]+|posters)\//.test(src || "");

